CREATE TABLE app_user(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password text NOT NULL, role text NOT NULL CHECK(role IN ('USER','OPERATOR','ADMIN')), synthetic boolean NOT NULL DEFAULT false);
CREATE TABLE auth_token(token text PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,expires_at timestamptz NOT NULL);
CREATE TABLE venue(id uuid PRIMARY KEY,name text NOT NULL);
CREATE TABLE event(id uuid PRIMARY KEY,venue_id uuid REFERENCES venue,title text NOT NULL,description text NOT NULL,art text NOT NULL,starts_at timestamptz NOT NULL,price integer NOT NULL CHECK(price>=0),rows integer NOT NULL CHECK(rows BETWEEN 1 AND 26),cols integer NOT NULL CHECK(cols BETWEEN 1 AND 30),version bigint NOT NULL DEFAULT 0,lab boolean NOT NULL DEFAULT false);
CREATE TABLE hold(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,event_id uuid NOT NULL REFERENCES event,expires_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('HELD','RELEASED','BOOKED','EXPIRED')),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE booking(id uuid PRIMARY KEY,reference text UNIQUE NOT NULL,user_id uuid NOT NULL REFERENCES app_user,event_id uuid NOT NULL REFERENCES event,hold_id uuid UNIQUE NOT NULL REFERENCES hold,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE seat(event_id uuid NOT NULL REFERENCES event,label text NOT NULL,row_no integer NOT NULL,col_no integer NOT NULL,hold_id uuid REFERENCES hold,booking_id uuid REFERENCES booking,PRIMARY KEY(event_id,label),UNIQUE(event_id,row_no,col_no),CHECK(booking_id IS NULL OR hold_id IS NULL));
CREATE TABLE hold_item(hold_id uuid NOT NULL REFERENCES hold,event_id uuid NOT NULL,label text NOT NULL,PRIMARY KEY(hold_id,label),FOREIGN KEY(event_id,label) REFERENCES seat(event_id,label));
CREATE TABLE booking_item(booking_id uuid NOT NULL REFERENCES booking,event_id uuid NOT NULL,label text NOT NULL,PRIMARY KEY(event_id,label),FOREIGN KEY(event_id,label) REFERENCES seat(event_id,label));
CREATE TABLE checkout(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user,hold_id uuid NOT NULL REFERENCES hold,idem_key text NOT NULL,mode text NOT NULL,status text NOT NULL,ready_at timestamptz NOT NULL,booking_id uuid REFERENCES booking,UNIQUE(user_id,idem_key));
CREATE TABLE payment(id uuid PRIMARY KEY,checkout_id uuid UNIQUE NOT NULL REFERENCES checkout,status text NOT NULL,amount integer NOT NULL CHECK(amount>=0));
CREATE TABLE lab_job(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES app_user,event_id uuid NOT NULL REFERENCES event,scenario text NOT NULL,attempts integer NOT NULL,concurrency integer NOT NULL,status text NOT NULL,completed integer NOT NULL DEFAULT 0,cancel_requested boolean NOT NULL DEFAULT false,result jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE UNIQUE INDEX one_running_lab ON lab_job((true)) WHERE status='RUNNING';
CREATE TABLE audit(id bigserial PRIMARY KEY,at timestamptz NOT NULL DEFAULT clock_timestamp(),actor uuid,event_id uuid,operation text NOT NULL,outcome text NOT NULL,correlation text NOT NULL,details text NOT NULL);
CREATE INDEX hold_owner ON hold(user_id,expires_at); CREATE INDEX hold_event ON hold(event_id);CREATE INDEX audit_page ON audit(id DESC);CREATE INDEX checkout_due ON checkout(ready_at) WHERE status='PENDING';CREATE INDEX seats_hold ON seat(hold_id);CREATE INDEX bookings_owner ON booking(user_id,created_at DESC);
